using System;using System.Linq;using System.IO;using System.Text;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using Frociart;
internal static class InlineCycleCanvasTests {
 static int checks;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(F).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
 static object Get(object o,string name){return o.GetType().GetField(name,F).GetValue(o);}
 static void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}
 static void Pump(int ms){var watch=System.Diagnostics.Stopwatch.StartNew();while(watch.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(4);}}
 static Point Center(FlowCanvas canvas,string id){var node=canvas.Diagram.Nodes.Single(n=>n.Id==id);var b=(RectangleF)Call(canvas,"DisplayBounds",node);return Point.Round((PointF)Call(canvas,"WorldToClient",new PointF(b.X+b.Width/2,b.Y+b.Height/2)));}
 static void Mouse(FlowCanvas canvas,string kind,Point at){Call(canvas,kind,new MouseEventArgs(MouseButtons.Left,1,at.X,at.Y,0));}
 static FlowCycleFold.Projection Scene(FlowCanvas c){Call(c,"EnsureScene");return(FlowCycleFold.Projection)Get(c,"foldProjection");}
 static string Enc(Diagram d){return Encoding.UTF8.GetString(DiagramIO.EncodeDocument(d));}
 static string Run(Diagram d){var r=new Interpreter(d);for(int i=0;i<1000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();Check(r.State==RuntimeState.Completed,"Source graph completes: "+r.Error);return r.OutputText;}
 static byte[] Pixels(Bitmap image){var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),System.Drawing.Imaging.ImageLockMode.ReadOnly,System.Drawing.Imaging.PixelFormat.Format32bppArgb);try{byte[] bytes=new byte[Math.Abs(data.Stride)*data.Height];System.Runtime.InteropServices.Marshal.Copy(data.Scan0,bytes,0,bytes.Length);return bytes;}finally{image.UnlockBits(data);}}
 [STAThread]static int Main(string[] args){MainForm main=null;try{Application.EnableVisualStyles();Control.CheckForIllegalCrossThreadCalls=true;UiMotion.SetEnabled(true);
  main=new MainForm(null,true);main.Size=new Size(1250,900);main.Show();var d=FlowPseudocode.Decode("PER i DA 1 A 3 PASSO 1 FAI\nSTAMPA i\nFINE PER");var info=FlowCycle.Find(d).Single();d.Nodes.Single(n=>n.Id==info.Check).Breakpoint=true;d.Nodes.Single(n=>n.Id==info.Check).BreakpointCondition="i=2";main.SetDocument(d,null,false);var c=main.Canvas;c.SnapToGrid=false;Pump(100);string original=Enc(d);int history=((System.Collections.ICollection)Get(main,"undo")).Count;
  c.FoldAllCycles(true);Pump(420);var p=Scene(c);Check(p!=null&&p.Cards.Count==1&&ReferenceEquals(c.Diagram,d),"Main canvas shows capsule over original document");Check(((System.Collections.ICollection)Get(main,"undo")).Count==history,"View toggle preserves algorithm undo stack");Check(Run(d)=="1\n2\n3".Replace("\n",Environment.NewLine),"Native collapsed loop executes original instructions");c.FitToView();Pump(50);
  var at=Center(c,info.Entry);Mouse(c,"OnMouseDown",at);Mouse(c,"OnMouseUp",at);Check(new HashSet<string>(c.SelectedNodeIds).SetEquals(info.Members),"Canvas click selects entire collapsed loop");Check((FlowNode)Call(c,"HitNode",(PointF)Call(c,"ClientToWorld",at))==d.Nodes.Single(n=>n.Id==info.Entry),"Hit testing returns actual source node");
  var positions=d.Nodes.ToDictionary(n=>n.Id,n=>new PointF(n.X,n.Y));var oldDisplay=(RectangleF)Call(c,"DisplayBounds",d.Nodes.Single(n=>n.Id==info.Entry));Point to=new Point(at.X+66,at.Y+35);Mouse(c,"OnMouseDown",at);Mouse(c,"OnMouseMove",to);Mouse(c,"OnMouseUp",to);Pump(420);var moved=main.Document;var delta=new PointF(moved.Nodes.Single(n=>n.Id==info.Entry).X-positions[info.Entry].X,moved.Nodes.Single(n=>n.Id==info.Entry).Y-positions[info.Entry].Y);Check(delta.X>30&&delta.Y>15,"Native group drag commits movement");foreach(var node in moved.Nodes){var old=positions[node.Id];Check(info.Members.Contains(node.Id)?Math.Abs(node.X-old.X-delta.X)<.02f&&Math.Abs(node.Y-old.Y-delta.Y)<.02f:node.X==old.X&&node.Y==old.Y,"Only the complete group moves");}var released=(RectangleF)Call(c,"DisplayBounds",moved.Nodes.Single(n=>n.Id==info.Entry));Check(Math.Abs(released.X-oldDisplay.X-delta.X)<.1f&&Math.Abs(released.Y-oldDisplay.Y-delta.Y)<.1f,"Capsule stays where released");Call(main,"Undo");Pump(400);Check(main.Document.Nodes.Single(n=>n.Id==info.Entry).X==positions[info.Entry].X&&Scene(c)!=null,"Undo restores position and folded view");Call(main,"Redo");Pump(400);Check(Scene(c)!=null,"Redo retains view");
  c.SelectNodes(info.Members);int count=main.Document.Nodes.Count;var duplicate=c.DuplicateSelected();Pump(420);Check(duplicate!=null&&main.Document.Nodes.Count==count+info.Members.Count,"Duplicate copies every executable member");Check(main.Document.Nodes.Where(n=>c.SelectedNodeIds.Contains(n.Id)).Any(n=>n.Breakpoint&&n.BreakpointCondition=="i=2"),"Duplicate retains debugger metadata");Check(Scene(c).Cards.Count==2,"Copied loop stays a capsule with a free exit");Check(Scene(c).Cards.Values.Any(v=>v.Exit==null),"Copied free exit is explicitly represented");Call(main,"Undo");Pump(420);Check(main.Document.Nodes.Count==count&&Scene(c).Cards.Count==1,"Duplicate undo restores original graph");
  c.SelectNodes(info.Members);Diagram fragment=null;c.ClipboardWrite=value=>fragment=FlowClipboard.Decode(FlowClipboard.Encode(value));c.CopySelection();Check(fragment!=null&&fragment.Nodes.Count==info.Members.Count,"Copy captures full native group");c.ClipboardRead=()=>fragment;Call(c,"PasteSelection",new PointF(900,400));Pump(420);Check(main.Document.Nodes.Count==count+info.Members.Count&&Scene(c).Cards.Count==2,"Paste retains compact cycle through actual clipboard codec");Call(main,"Undo");Pump(400);
  c.SelectNodes(info.Members);c.DeleteSelection();Pump(400);Check(main.Document.Nodes.All(n=>!info.Members.Contains(n.Id)),"Delete removes complete collapsed group");Call(main,"Undo");Pump(420);Check(Run(main.Document)=="1\n2\n3".Replace("\n",Environment.NewLine)&&Scene(c)!=null,"Delete undo restores executable folded loop");
  c.CurrentNodeId=info.BodyEntry;Pump(30);Check(c.CurrentNodeId==info.BodyEntry&&Scene(c).Owner(c.CurrentNodeId)==info.Entry,"Runtime identity stays original while highlight maps to capsule");Call(main,"ArrangeDiagram");Pump(450);Check(Scene(c)!=null&&main.Document.Edges.All(e=>e.From!=null&&e.To!=null),"Native Riordina accepts folded cycles");Check(Run(main.Document)=="1\n2\n3".Replace("\n",Environment.NewLine),"Riordina preserves executable loop");
  using(var image=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(args[0],"pc-inline-folded.png"));}
  string save=Path.Combine(args[0],"native-inline.frociart");DiagramIO.Save(save,main.Project);var loaded=DiagramIO.Load(save);Check(loaded.Nodes.Any(n=>n.FoldedCycle)&&Run(loaded)=="1\n2\n3".Replace("\n",Environment.NewLine),"Saved project preserves presentation and runtime");c.SelectNode(info.BodyEntry);Pump(420);Check(Scene(c)==null&&c.SelectedNodeId==info.BodyEntry,"Editing original body reveals its instructions");
  c.SelectNode(info.Check);Call(c,"EnsureContextMenu");Call(c,"ConfigureContextMenu",Center(c,info.Check));var menu=(ToolStripMenuItem)Get(c,"foldCycleMenu");Check(menu.Available&&c.CanFoldSelection,"Context menu exposes collapse for selected cycle");menu.PerformClick();Pump(420);Check(Scene(c)!=null,"Real context-menu action folds on the canvas");UiMotion.SetEnabled(false);c.FoldAllCycles(false);Check(Scene(c)==null,"Reduced-motion path opens immediately");
  UiMotion.SetEnabled(true);c.FoldAllCycles(true);Pump(420);using(var foldedImage=c.RenderExportBitmap(1)){Check(Scene(c)!=null,"Export keeps compact view state");c.FoldAllCycles(false);Pump(420);using(var expandedImage=c.RenderExportBitmap(1))Check(foldedImage.Width==expandedImage.Width&&foldedImage.Height==expandedImage.Height&&Pixels(foldedImage).SequenceEqual(Pixels(expandedImage)),"Image export contains identical full original graph in both views");}c.FoldAllCycles(true);Pump(420);c.FitToView();at=Center(c,info.Entry);Mouse(c,"OnMouseDown",at);Mouse(c,"OnMouseUp",at);Mouse(c,"OnMouseDown",at);Call(c,"OnMouseDoubleClick",new MouseEventArgs(MouseButtons.Left,2,at.X,at.Y,0));Mouse(c,"OnMouseUp",at);Pump(420);Check(Scene(c)==null,"Native double-click expands capsule without editing its helper text");
  main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();Console.WriteLine("INLINE_CYCLE_PC_CANVAS PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);if(main!=null){main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();}return 1;}}
}
